import { test, expect } from '@playwright/test';

test.describe('Virtual Scroll List - 10,000 Rows', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/virtual-scroll');
  });

  test('should render and scroll through 10,000 rows without lag', async ({ page }) => {
    // Verify the list container is visible
    const listContainer = page.getByRole('region', { name: /virtual scroll list/i });
    await expect(listContainer).toBeVisible();

    // Verify the initial row count is displayed
    const rowCount = page.getByText('10,000 rows');
    await expect(rowCount).toBeVisible();

    // Scroll to the bottom of the list
    const scrollButton = page.getByRole('button', { name: /scroll to bottom/i });
    await scrollButton.click();

    // Wait for the list to render all rows
    await page.waitForTimeout(1000);

    // Verify the last row is visible
    const lastRow = page.getByText('Row 10000');
    await expect(lastRow).toBeVisible();

    // Verify the scroll indicator shows the full height
    const scrollIndicator = page.getByRole('status', { name: /scroll indicator/i });
    await expect(scrollIndicator).toContainText('10000');

    // Verify the scroll position is at the bottom
    const scrollPosition = page.getByRole('status', { name: /scroll position/i });
    await expect(scrollPosition).toContainText('10000');
  });

  test('should handle rapid scrolling and maintain performance', async ({ page }) => {
    // Verify the list container is visible
    const listContainer = page.getByRole('region', { name: /virtual scroll list/i });
    await expect(listContainer).toBeVisible();

    // Scroll to the middle of the list
    const scrollButton = page.getByRole('button', { name: /scroll to middle/i });
    await scrollButton.click();

    // Wait for the list to render the middle section
    await page.waitForTimeout(1000);

    // Verify a middle row is visible
    const middleRow = page.getByText('Row 5000');
    await expect(middleRow).toBeVisible();

    // Scroll rapidly to the top
    const scrollUpButton = page.getByRole('button', { name: /scroll to top/i });
    await scrollUpButton.click();

    // Wait for the list to render the top section
    await page.waitForTimeout(1000);

    // Verify the first row is visible
    const firstRow = page.getByText('Row 1');
    await expect(firstRow).toBeVisible();

    // Verify the scroll position is at the top
    const scrollPosition = page.getByRole('status', { name: /scroll position/i });
    await expect(scrollPosition).toContainText('0');

    // Verify the list is responsive to scroll events
    const scrollEvent = page.evaluate(() => {
      const list = document.querySelector('[data-testid="virtual-scroll-list"]');
      if (list) {
        list.scrollTop = 50000;
      }
    });

    // Verify the scroll position updates after programmatic scroll
    await expect(scrollPosition).toContainText('50000');
  });
});
